function parseJsonObject(raw, who) {
  const m = raw.match(/\{[\s\S]*\}/)
  if (!m) throw new Error(`${who} \u043D\u0435 \u0432\u0435\u0440\u043D\u0443\u043B JSON`)
  return JSON.parse(m[0])
}
